            boolean atLoad = ex != null && thrownAtLoad(ex);
            String unmet = atLoad ? generalTestFailed("load_", keys, outs, errs, exc) : null;
            boolean refused = atLoad && unmet == null;
            boolean ranClean = ex == null && !anyFails;
